// Analisar contexto e determinar tipo de relacionamento
const contexto = JSON.parse($json.contexto);
const mensagem = contexto.mensagem_original.toLowerCase();
const cliente = contexto.dados_entrada.cliente;
const canal = contexto.canal;

// Determinar tipo de interação de relacionamento
let tipo_relacionamento = 'geral';
let intencao_cliente = 'informacao';

// Detectar intenções específicas
const intencoes = {
  feedback: ['feedback', 'avaliação', 'opinião', 'como foi', 'experiência'],
  novidades: ['novidades', 'novo', 'lançamento', 'disponível', 'chegou'],
  status_processo: ['status', 'andamento', 'processo', 'documentos', 'aprovação'],
  reagendamento: ['reagendar', 'remarcar', 'mudar horário', 'cancelar'],
  indicacao: ['indicar', 'amigo', 'conhecido', 'família', 'recomendação'],
  satisfacao: ['satisfeito', 'contente', 'feliz', 'obrigado', 'parabéns'],
  reclamacao: ['problema', 'reclamação', 'insatisfeito', 'ruim', 'erro'],
  duvida: ['dúvida', 'pergunta', 'como', 'quando', 'onde', 'por que']
};

// Detectar intenção principal
for (const [intencao, palavras] of Object.entries(intencoes)) {
  if (palavras.some(palavra => mensagem.includes(palavra))) {
    intencao_cliente = intencao;
    break;
  }
}

// Determinar tipo de relacionamento baseado no histórico do cliente
if (cliente) {
  const ultimaInteracao = new Date(cliente.ultima_interacao);
  const agora = new Date();
  const diasSemInteracao = Math.floor((agora - ultimaInteracao) / (1000 * 60 * 60 * 24));

  if (diasSemInteracao > 30) {
    tipo_relacionamento = 'reativacao';
  } else if (diasSemInteracao > 7) {
    tipo_relacionamento = 'follow_up';
  } else {
    tipo_relacionamento = 'ativo';
  }

  // Verificar se tem visitas agendadas
  if (cliente.status === 'ativo') {
    tipo_relacionamento = 'pos_visita';
  }
}

// Analisar sentimento da mensagem
let sentimento = 'neutro';
const palavrasPositivas = ['bom', 'ótimo', 'excelente', 'perfeito', 'adorei', 'gostei', 'obrigado'];
const palavrasNegativas = ['ruim', 'péssimo', 'problema', 'erro', 'insatisfeito', 'reclamação'];

if (palavrasPositivas.some(palavra => mensagem.includes(palavra))) {
  sentimento = 'positivo';
} else if (palavrasNegativas.some(palavra => mensagem.includes(palavra))) {
  sentimento = 'negativo';
}

return {
  json: {
    contexto_original: contexto,
    tipo_relacionamento: tipo_relacionamento,
    intencao_cliente: intencao_cliente,
    sentimento: sentimento,
    cliente_dados: cliente,
    canal: canal,
    origem: 'interacao_direta'
  }
};

// Gerar resposta personalizada de relacionamento
const dados = $json;
const tipo = dados.tipo_relacionamento;
const intencao = dados.intencao_cliente;
const sentimento = dados.sentimento;
const cliente = dados.cliente_dados;
const canal = dados.canal;
const historico = $input.all().slice(1); // Histórico do segundo input

const nomeCliente = cliente?.nome?.split(' ')[0] || 'Cliente';

// Templates de resposta por tipo de relacionamento
const templates = {
  ativo: {
    whatsapp: {
      feedback: `Oi ${nomeCliente}! 😊\n\nQue bom ter seu feedback! Sua opinião é muito importante para nós.\n\nComo foi sua experiência até agora? Tem alguma sugestão de como podemos melhorar? 💭`,
      novidades: `Oi ${nomeCliente}! 🏠\n\nTenho novidades incríveis para você! Chegaram imóveis novos que podem te interessar.\n\nQuer que eu te envie as opções que combinam com seu perfil? 📱`,
      status_processo: `Oi ${nomeCliente}! 📋\n\nVou verificar o status do seu processo agora mesmo!\n\nEm alguns minutos te envio todas as atualizações. Qualquer dúvida, é só falar! ✅`,
      satisfacao: `${nomeCliente}, que alegria receber seu retorno! 🎉\n\nFicamos muito felizes em saber que está satisfeito(a)! \n\nContinuamos trabalhando para te oferecer o melhor atendimento sempre! 💪`,
      reclamacao: `${nomeCliente}, peço desculpas pelo ocorrido! 😔\n\nVou resolver isso imediatamente e garantir que não aconteça novamente.\n\nPode me dar mais detalhes para eu entender melhor a situação? 🔍`,
      duvida: `Oi ${nomeCliente}! 🤔\n\nClaro, vou esclarecer sua dúvida!\n\nPode me explicar melhor o que você gostaria de saber? Estou aqui para ajudar! 💡`
    },
    email: {
      feedback: `Olá ${nomeCliente}!\n\nObrigado por entrar em contato. Seu feedback é muito valioso para nós.\n\nGostaria de saber mais detalhes sobre sua experiência para continuarmos melhorando nossos serviços.`,
      novidades: `Olá ${nomeCliente}!\n\nTemos novidades que podem interessar você! Novos imóveis foram cadastrados em nosso sistema.\n\nGostaria de receber uma seleção personalizada baseada em suas preferências?`,
      status_processo: `Olá ${nomeCliente}!\n\nVou verificar o status atual do seu processo e te enviar todas as informações atualizadas em breve.\n\nQualquer dúvida adicional, estou à disposição.`
    }
  },

  follow_up: {
    whatsapp: `Oi ${nomeCliente}! 👋\n\nTudo bem? Faz um tempinho que não conversamos!\n\nComo anda sua busca pelo imóvel ideal? Surgiu alguma dúvida ou posso te ajudar com alguma coisa? 🏠\n\nTenho algumas novidades que podem te interessar! 😊`,
    email: `Olá ${nomeCliente}!\n\nEspero que esteja tudo bem! \n\nGostaria de saber como anda sua busca pelo imóvel ideal e se posso ajudar em alguma coisa.\n\nTemos recebido novos imóveis que podem atender suas necessidades.`
  },

  reativacao: {
    whatsapp: `Oi ${nomeCliente}! 😊\n\nSentimos sua falta! Como você está?\n\nVi que faz um tempo que não conversamos... Ainda está procurando imóvel? 🏠\n\nTemos muitas novidades incríveis que chegaram! Quer dar uma olhada? 👀`,
    email: `Olá ${nomeCliente}!\n\nSentimos sua falta! Espero que esteja tudo bem.\n\nGostaria de saber se ainda tem interesse em imóveis, pois temos recebido muitas opções novas.\n\nSe desejar, posso enviar uma seleção atualizada baseada em suas preferências anteriores.`
  },

  pos_visita: {
    whatsapp: `Oi ${nomeCliente}! 🏠\n\nComo foi a visita? Gostou do imóvel?\n\nFiquei curioso(a) para saber sua impressão! \n\nSe tiver alguma dúvida ou quiser ver outros imóveis, é só falar! 😊`,
    email: `Olá ${nomeCliente}!\n\nGostaria de saber como foi sua visita ao imóvel.\n\nSua opinião é muito importante para nós. Se tiver interesse ou dúvidas, estou à disposição para ajudar.`
  }
};

// Selecionar resposta apropriada
let resposta = '';

if (templates[tipo] && templates[tipo][canal] && templates[tipo][canal][intencao]) {
  resposta = templates[tipo][canal][intencao];
} else if (templates[tipo] && templates[tipo][canal]) {
  resposta = templates[tipo][canal];
} else if (templates[tipo] && templates[tipo].whatsapp) {
  resposta = templates[tipo].whatsapp;
} else {
  // Resposta padrão
  if (canal === 'whatsapp') {
    resposta = `Oi ${nomeCliente}! 😊\n\nObrigado por entrar em contato!\n\nComo posso te ajudar hoje? Estou aqui para esclarecer qualquer dúvida! 💪`;
  } else {
    resposta = `Olá ${nomeCliente}!\n\nObrigado por entrar em contato. Como posso ajudá-lo hoje?`;
  }
}

// Personalizar baseado no sentimento
if (sentimento === 'negativo' && !resposta.includes('desculpas')) {
  if (canal === 'whatsapp') {
    resposta += `\n\n🚨 *Atenção especial:* Vou priorizar seu atendimento para resolver qualquer questão rapidamente!`;
  } else {
    resposta += `\n\nVou priorizar seu atendimento para resolver qualquer questão o mais rápido possível.`;
  }
}

// Determinar próximas ações
let proximas_acoes = [];
let requer_hitl = false;

if (sentimento === 'negativo' || intencao === 'reclamacao') {
  requer_hitl = true;
  proximas_acoes.push('escalar_para_supervisor');
}

if (intencao === 'novidades') {
  proximas_acoes.push('enviar_imoveis_novos');
}

if (tipo === 'reativacao') {
  proximas_acoes.push('atualizar_preferencias');
}

return {
  json: {
    resposta: resposta,
    tipo_relacionamento: tipo,
    intencao_detectada: intencao,
    sentimento: sentimento,
    proximas_acoes: proximas_acoes,
    requer_hitl: requer_hitl,
    dados_contexto: dados
  }
};

// Processar lista de clientes para follow-up
const clientes = $input.all();
const mensagensFollowUp = [];

for (const clienteItem of clientes) {
  const cliente = clienteItem.json;
  const nome = cliente.nome?.split(' ')[0] || 'Cliente';
  const diasSemContato = cliente.dias_sem_contato;

  let mensagem = '';

  if (diasSemContato <= 10) {
    // Follow-up suave
    mensagem = `Oi ${nome}! 😊\n\nTudo bem? Como anda sua busca pelo imóvel ideal?\n\nTenho algumas novidades que podem te interessar! Quer dar uma olhada? 🏠`;
  } else if (diasSemContato <= 20) {
    // Follow-up médio
    mensagem = `Oi ${nome}! 👋\n\nSentimos sua falta! Como você está?\n\nChegaram imóveis novos incríveis! Que tal darmos uma olhada juntos? 🎯`;
  } else {
    // Follow-up de reativação
    mensagem = `Oi ${nome}! 🌟\n\nOlha só quem apareceu nas nossas pesquisas! Como você está?\n\nTemos muitas novidades desde nossa última conversa. Ainda está procurando imóvel? 🏠✨`;
  }

  mensagensFollowUp.push({
    cliente_id: cliente.id,
    nome: cliente.nome,
    telefone: cliente.telefone,
    email: cliente.email,
    mensagem: mensagem,
    dias_sem_contato: diasSemContato,
    score: cliente.score_qualificacao
  });
}

return {
  json: {
    total_clientes: mensagensFollowUp.length,
    mensagens_follow_up: mensagensFollowUp,
    data_processamento: new Date().toISOString()
  }
};

// Gerar newsletter mensal personalizada
const clientes = $input.all();

// Buscar imóveis em destaque (simulado - seria uma query real)
const imoveisDestaque = [
  {
    codigo: 'IMO001234',
    tipo: 'Apartamento',
    bairro: 'Vila Madalena',
    valor: 850000,
    quartos: 3,
    destaque: 'Lançamento exclusivo'
  },
  {
    codigo: 'IMO001235', 
    tipo: 'Casa',
    bairro: 'Pinheiros',
    valor: 1200000,
    quartos: 4,
    destaque: 'Oportunidade única'
  }
];

const newslettersPersonalizadas = [];

for (const clienteItem of clientes) {
  const cliente = clienteItem.json;
  const nome = cliente.nome?.split(' ')[0] || 'Cliente';

  // Personalizar baseado no perfil do cliente
  let imoveisFiltrados = imoveisDestaque;
  if (cliente.localizacao_preferida) {
    imoveisFiltrados = imoveisDestaque.filter(i => 
      i.bairro.toLowerCase().includes(cliente.localizacao_preferida.toLowerCase())
    );
  }

  if (imoveisFiltrados.length === 0) {
    imoveisFiltrados = imoveisDestaque.slice(0, 2);
  }

  const imoveisFormatados = imoveisFiltrados.map(imovel => 
    `🏠 ${imovel.codigo} - ${imovel.tipo}\n` +
    `📍 ${imovel.bairro}\n` +
    `💰 R$ ${imovel.valor.toLocaleString('pt-BR')}\n` +
    `🛏️ ${imovel.quartos} quartos\n` +
    `⭐ ${imovel.destaque}`
  ).join('\n\n');

  const newsletter = {
    cliente_id: cliente.id,
    nome: cliente.nome,
    email: cliente.email,
    assunto: `${nome}, novidades incríveis da nossa imobiliária! 🏠`,
    conteudo: `Olá ${nome}!\n\n` +
              `Esperamos que esteja tudo bem! 😊\n\n` +
              `Este mês temos novidades especiais para você:\n\n` +
              `🌟 DESTAQUES DO MÊS:\n\n${imoveisFormatados}\n\n` +
              `📈 MERCADO IMOBILIÁRIO:\n` +
              `O mercado está aquecido e é um ótimo momento para investir!\n\n` +
              `💡 DICA DO MÊS:\n` +
              `Financiamentos estão com taxas atrativas. Que tal simular?\n\n` +
              `🤝 Estamos aqui para ajudar você a encontrar o imóvel dos seus sonhos!\n\n` +
              `Qualquer dúvida, é só responder este e-mail!\n\n` +
              `Abraços,\nEquipe Imobiliária`,
    total_interacoes: cliente.total_interacoes || 0
  };

  newslettersPersonalizadas.push(newsletter);
}

return {
  json: {
    total_newsletters: newslettersPersonalizadas.length,
    newsletters: newslettersPersonalizadas,
    data_processamento: new Date().toISOString()
  }
};
